contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function doing the property-based test
    function run(address potentialOwner, address senderForWithdraw, address payable recipient, uint256 deposit) public payable {
        require(address(this).balance >= deposit);
        // Deploy-time owner is already set when c was constructed by the harness; we accept that.
        // Record initial observable values
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;

        // Optionally send Ether into c to create balance if deposit > 0
        if (deposit > 0) {
            // send Ether to c using its payable fallback
            (bool ok,) = address(c).call{value: deposit}("");
            // ensure the transfer to c succeeded in this test setup
            require(ok);
        }

        // After funding, read balance
        uint256 balanceFunded = address(c).balance;

        // Prepare to call withdrawAll as if from this contract but we want to simulate both owner and non-owner callers.
        // The checker runs this single transaction where msg.sender for calls on c is this contract; we cannot change that.
        // To simulate owner vs non-owner, we will check two cases logically:
        // - If this contract is the owner, calling withdrawAll should succeed and transfer all balance to recipient.
        // - If this contract is not the owner, calling withdrawAll should revert and balance should stay the same.

        bool reverted;
        // perform the call: withdrawAll is a public non-payable function that sends all Ether to recipient
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observable values
        address ownerAfter = c.owner();
        uint256 balanceAfter = address(c).balance;
        uint256 receiverBalanceAfter = address(this).balance; // note: recipient may be arbitrary; if it's this contract, we can observe

        // Now assert the general rule in terms of observable values and the revert flag.
        // Case A: If this contract was the owner at call time, the call must not revert, c.balance must become 0,
        // and owner must remain unchanged. Additionally, if recipient == address(this) then this contract's balance must increase by the drained amount.
        // Case B: If this contract was not the owner, the call must revert and c.balance must remain unchanged and owner unchanged.

        // Expressed as a single boolean formula:
        assert(
            // owner is immutable via public interface for our cases
            ownerAfter == ownerBefore && (
                // If the caller (this contract) was ownerBefore
                (ownerBefore == address(this) && reverted == false && balanceAfter == 0) ||
                // If caller was not ownerBefore
                (ownerBefore != address(this) && reverted == true && balanceAfter == balanceFunded)
            )
        );
    }

    receive() external payable {}
}

