    function run(address ownerAddress, address payable recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);
        // Ensure the contract C was constructed with the given ownerAddress (the checker deploys a fresh C with some owner)
        // We cannot redeploy C here; instead we observe c.owner() and use it accordingly.
        address observedOwner = c.owner();

        // Fund contract c by sending Ether from this test contract
        // Transfer fund into c
        (bool sent, ) = address(c).call{value: fund}("");
        // call may succeed (fallback payable exists), ensure it did
        require(sent);

        uint256 beforeBal = address(c).balance;
        // Two cases to check: if this test contract is the owner (so msg.sender for withdraw will be this contract)
        // But withdrawAll requires msg.sender == owner; when we call c.withdrawAll from here, msg.sender is this contract
        // So determine whether this InvMutTest is the owner
        bool amOwner = (observedOwner == address(this));

        bool reverted;
        // perform the call: attempt withdrawAll to recipient
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = address(c).balance;
        uint256 recipientBalAfter = recipient.balance;

        // General rule asserted:
        // - If this contract was owner, the call must not revert, and all Ether previously in c must have been transferred out (c balance == 0), and recipient's balance increased by exactly beforeBal.
        // - If this contract was not owner, the call must revert and c balance must be unchanged.
        assert((amOwner && !reverted && afterBal == 0 && recipientBalAfter >= beforeBal) || (!amOwner && reverted && afterBal == beforeBal));
    }

    receive() external payable {}
}

