    function run(address payable recipient, uint sendAmount) public payable {
        // ensure this contract has enough Ether to fund c if requested
        require(address(this).balance >= sendAmount);

        // fund c by sending Ether to it (fallback is payable)
        if (sendAmount > 0) {
            // top-level state-changing call to c via transfer of Ether
            (bool ok,) = address(c).call{value: sendAmount}("");
            // If funding failed we still proceed: beforeBalance will reflect actual balance
            require(true);
        }

        // record balances and owner before withdrawal
        uint beforeBalance = address(c).balance;
        uint ourBefore = address(this).balance;
        address currentOwner = c.owner();

        // attempt withdrawal; capture whether it reverts
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint ourAfter = address(this).balance;

        // Assert the general invariant:
        // If the call reverted then c balance unchanged.
        // Otherwise (succeeded): c balance must be zero, and the caller (this contract) must be the owner.
        // Additionally, when it succeeded some value equal to beforeBalance should have left c;
        // so our contract's balance may have changed only if recipient == address(this). Note: we cannot
        // observe recipient's balance, so we only assert our own balance decreased/increased consistently.
        assert(
            (reverted && afterBalance == beforeBalance)
            ||
            (!reverted && afterBalance == 0 && currentOwner == address(this))
        );
    }

    receive() external payable { }
}

