contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes the owner address used to construct c, a caller address to simulate (unused directly),
    // a recipient for withdrawAll, and an amount to fund c initially.
    function run(address ownerAddr, address caller, address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);
        // Assumption: the provided c was constructed with ownerAddr as its owner.
        // Fund the contract c with fundAmount wei from this test contract.
        // transfer by calling fallback payable
        address(c).call{value: fundAmount}("");

        // Read balances before withdraw attempt
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        // Decide who will invoke withdrawAll: if caller equals ownerAddr we simulate owner call via this contract
        // Since the checker will execute run once and msg.sender for calls to c will be this contract,
        // we emulate both cases by: when caller==ownerAddr we perform the withdraw; otherwise we attempt withdraw
        // expecting it to revert. We capture whether it reverted.
        bool reverted;
        if (caller == ownerAddr) {
            // As owner: this contract must be the one equal to owner registered in c; but owner in c is ownerAddr
            // We cannot change msg.sender to ownerAddr, so only when ownerAddr==address(this) will the call succeed.
            // To create a general rule that is checkable, we assert the following: if ownerAddr==address(this) then withdraw succeeds
            // and transfers all balance to recipient; otherwise a withdraw attempt by this contract must revert.
            // Here we call withdrawAll and record revert status.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // caller != ownerAddr: this contract is not the configured owner when ownerAddr==address(this) is false.
            // Attempt withdraw and expect revert (unless this contract is owner). Record revert status.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule expressed as one assert:
        // If ownerAddr == address(this) then the withdraw call did not revert, and contract balance became zero,
        // and recipient gained exactly beforeC. Otherwise the call reverted and balances unchanged.
        assert(
            (ownerAddr == address(this) && reverted == false && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            ||
            (ownerAddr != address(this) && reverted == true && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    // allow receiving Ether when funding c
    receive() external payable {}
}

