    function run(address payable _recipient, uint256 fundAmount, bool callerIsOwner) public payable {
        require(address(this).balance >= fundAmount, "not enough balance to fund");
        // Fund contract c with supplied amount
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // Read pre-state
        address preOwner = c.owner();
        uint256 preBalance = address(c).balance;
        // Decide who will attempt the withdrawal: if callerIsOwner==true, we attempt a withdraw from the owner by making the test contract act as owner proxy.
        // We cannot change msg.sender of c calls; msg.sender will always be this contract. Therefore we model two cases:
        // - If callerIsOwner is true, require that c.owner() == address(this) so the call should succeed.
        // - If callerIsOwner is false, require that c.owner() != address(this) so the call should revert.
        if (callerIsOwner) {
            require(preOwner == address(this), "to test owner-withdraw path, this contract must be owner");
        } else {
            require(preOwner != address(this), "to test non-owner revert path, this contract must NOT be owner");
        }

        // Attempt withdraw and capture whether it reverted
        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 postBalance = address(c).balance;
        uint256 recipientBalance = address(_recipient).balance;

        // General rule:
        // - If callerIsOwner (and thus this contract is owner) the call must NOT revert and the contract balance becomes zero and recipient gained exactly preBalance.
        // - If callerIsOwner is false (this contract not owner) the call must revert and the contract balance is unchanged.
        assert(
            callerIsOwner
            ? (
                reverted == false
                && postBalance == 0
                && recipientBalance >= preBalance // recipient gained at least preBalance (could have been funded elsewhere), but must be >=
            )
            : (
                reverted == true
                && postBalance == preBalance
            )
        );
    }

    receive() external payable {}
}

